<?php
declare(strict_types=1); function mg_personal_workflows_group_snapshot_list(PDO $pdo, int $organizerUserId, int $groupId, int $listId, ?int $recipientUserId = null, ?int $recipientContactId = null): array { $stmt=$pdo->prepare("SELECT m.contact_user_id,m.user_contact_id,
        COALESCE(c.display_name,pp.display_name,u.display_name,u.full_name,'Contact') display_name
        FROM user_contact_list_members m
        LEFT JOIN user_contacts c ON c.id=m.user_contact_id AND c.owner_user_id=m.owner_user_id
        LEFT JOIN users u ON u.id=m.contact_user_id
        LEFT JOIN public_profiles pp ON pp.user_id=m.contact_user_id
        WHERE m.owner_user_id=? AND m.list_id=? ORDER BY display_name"); $stmt->execute([$organizerUserId,$listId]); $added=0;$skipped=0; foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $member) { $linked=$member['contact_user_id']!==null?(int)$member['contact_user_id']:null; $private=$member['user_contact_id']!==null?(int)$member['user_contact_id']:null; if(($linked!==null && $linked===$recipientUserId)||($private!==null && $private===$recipientContactId)) {$skipped++;continue;} if($linked!==null) { $eligibility=mg_user_contact_list_eligibility_detail($pdo,$organizerUserId,$linked); if(empty($eligibility['eligible'])) {$skipped++;continue;} } $insert=$pdo->prepare("INSERT IGNORE INTO user_group_gift_participants
            (public_id,group_gift_id,organizer_user_id,invited_user_id,private_contact_id,role_key,display_name_snapshot,status,created_at,updated_at)
            VALUES (?,?,?,?,?,'contributor',?,'draft',NOW(),NOW())"); $insert->execute([mg_public_uuid(),$groupId,$organizerUserId,$linked,$private,mg_personal_agent_text($member['display_name'],190)]); if($insert->rowCount()===1)$added++;else$skipped++; } return ['added'=>$added,'skipped'=>$skipped]; } function mg_personal_workflows_create_group_gift(PDO $pdo, int $userId, array $input): array { mg_personal_workflows_require_schema($pdo); $context=mg_personal_workflows_context($pdo,$userId,$input); $ids=mg_personal_workflows_context_columns($context); $title=mg_personal_agent_text($input['title'] ?? '',190); if($title==='') throw new InvalidArgumentException('Group gift title is required.'); $goal=mg_personal_workflows_cents($input['goal'] ?? null,false) ?? 0; if($goal<100) throw new InvalidArgumentException('Group gift goal must be at least 1.00.'); $min=mg_personal_workflows_cents($input['min_contribution'] ?? null); $max=mg_personal_workflows_cents($input['max_contribution'] ?? null); if($min!==null && $max!==null && $min>$max) throw new InvalidArgumentException('Minimum contribution cannot exceed maximum contribution.'); $deadline=mg_personal_agent_datetime($input['deadline_at'] ?? ''); if(strtotime($deadline)<=time()) throw new InvalidArgumentException('Group gift deadline must be in the future.'); $currency=mg_personal_agent_currency($input['currency'] ?? 'USD'); $description=mg_personal_agent_nullable_text($input['description'] ?? null,5000); $listId=null; $contributorListPublicId=mg_personal_agent_text($input['contributor_list_id'] ?? '',80); if($contributorListPublicId!=='' || ($context['type'] ?? '')==='list') { $listPublicId=$contributorListPublicId!==''?$contributorListPublicId:(string)$context['id']; $list=mg_user_contact_list_load($pdo,$userId,$listPublicId); if(!empty($list['is_archived'])) throw new RuntimeException('Archived lists cannot start group gifts.'); $listId=(int)$list['id_internal']; } $recipientContactId=in_array($context['type'] ?? '',['contact'],true)?($ids['user_contact_id'] ?? null):null; $recipientUserId=in_array($context['type'] ?? '',['linked_user'],true)?($ids['contact_user_id'] ?? null):null; $planId=null; $planPublicId=mg_personal_agent_text($input['plan_id'] ?? '',80); if($planPublicId!=='' || ($context['type'] ?? '')==='plan') { $resolvedPlanPublic=$planPublicId!==''?$planPublicId:(string)$context['id']; $planStmt=$pdo->prepare('SELECT id FROM user_gifting_plans WHERE owner_user_id=? AND public_id=? LIMIT 1'); $planStmt->execute([$userId,$resolvedPlanPublic]); $planId=(int)($planStmt->fetchColumn() ?: 0); if($planId<1) throw new RuntimeException('Gifting plan not found.'); } $publicId=mg_public_uuid(); $pdo->beginTransaction(); try { $pdo->prepare("INSERT INTO user_group_gifts
            (public_id,organizer_user_id,plan_id,list_id,recipient_user_contact_id,recipient_user_id,title,description,goal_cents,min_contribution_cents,max_contribution_cents,pledged_cents,currency,deadline_at,status,contribution_mode,contributor_names_visible,anonymous_allowed,created_at,updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,0,?,?,'draft','pledge_only',?,?,NOW(),NOW())") ->execute([$publicId,$userId,$planId,$listId,$recipientContactId,$recipientUserId,$title,$description,$goal,$min,$max,$currency,$deadline, mg_personal_workflows_bool($input['contributor_names_visible'] ?? true,true)?1:0, mg_personal_workflows_bool($input['anonymous_allowed'] ?? true,true)?1:0]); $groupId=(int)$pdo->lastInsertId(); $snapshot=['added'=>0,'skipped'=>0]; if($listId!==null) $snapshot=mg_personal_workflows_group_snapshot_list($pdo,$userId,$groupId,$listId,$recipientUserId,$recipientContactId); $pdo->commit(); mg_audit('user_group_gift.created','user_group_gift',['group_gift_id'=>$publicId,'goal_cents'=>$goal,'contribution_mode'=>'pledge_only','snapshot'=>$snapshot],$userId); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } $all=mg_personal_workflows_group_gifts($pdo,$userId); foreach($all['owned'] as $row) if($row['id']===$publicId) return $row+['snapshot'=>$snapshot]; throw new RuntimeException('Unable to load group gift.'); } function mg_personal_workflows_group_participants(PDO $pdo, int $organizerUserId, string $groupPublicId): array { $group=$pdo->prepare('SELECT id FROM user_group_gifts WHERE organizer_user_id=? AND public_id=? LIMIT 1'); $group->execute([$organizerUserId,$groupPublicId]); $groupId=(int)($group->fetchColumn() ?: 0); if($groupId<1) throw new RuntimeException('Group gift not found.'); $stmt=$pdo->prepare('SELECT public_id,role_key,display_name_snapshot,status,pledge_cents,is_anonymous,invite_message,invited_at,responded_at,invited_user_id,private_contact_id FROM user_group_gift_participants WHERE group_gift_id=? ORDER BY role_key,display_name_snapshot'); $stmt->execute([$groupId]); return array_map(static fn(array $row):array=>[ 'id'=>(string)$row['public_id'],'role'=>(string)$row['role_key'],'name'=>(string)$row['display_name_snapshot'],'status'=>(string)$row['status'], 'pledge'=>mg_personal_workflows_money($row['pledge_cents']!==null?(int)$row['pledge_cents']:null),'is_anonymous'=>(bool)$row['is_anonymous'], 'invite_message'=>(string)($row['invite_message'] ?? ''),'delivery'=>$row['invited_user_id']!==null?'in_app':'external_draft', 'invited_at'=>$row['invited_at'] ?: null,'responded_at'=>$row['responded_at'] ?: null, ],$stmt->fetchAll(PDO::FETCH_ASSOC)); } function mg_personal_workflows_update_group_gift(PDO $pdo, int $userId, string $publicId, string $action): array { $stmt=$pdo->prepare('SELECT id,status,title FROM user_group_gifts WHERE organizer_user_id=? AND public_id=? LIMIT 1'); $stmt->execute([$userId,$publicId]); $group=$stmt->fetch(PDO::FETCH_ASSOC); if(!$group) throw new RuntimeException('Group gift not found.'); $current=(string)$group['status']; $map=['open'=>'open','lock'=>'locked','fulfill'=>'fulfilled','close'=>'closed','cancel'=>'cancelled']; $allowed=['draft'=>['open','cancel'],'open'=>['lock','fulfill','close','cancel'],'locked'=>['fulfill','close','cancel'],'fulfilled'=>['close'],'closed'=>[],'cancelled'=>[]]; if(!isset($map[$action]) || !in_array($action,$allowed[$current] ?? [],true)) throw new RuntimeException('That group-gift transition is not allowed.'); $next=$map[$action]; $pdo->beginTransaction(); try { $pdo->prepare("UPDATE user_group_gifts SET status=?,opened_at=IF(?='open',NOW(),opened_at),closed_at=IF(?='closed',NOW(),closed_at),cancelled_at=IF(?='cancelled',NOW(),cancelled_at),updated_at=NOW() WHERE id=?") ->execute([$next,$next,$next,$next,(int)$group['id']]); $notifications=0; if($action==='open') { $participants=$pdo->prepare("SELECT id,invited_user_id,display_name_snapshot FROM user_group_gift_participants WHERE group_gift_id=? AND status='draft'"); $participants->execute([(int)$group['id']]); foreach($participants->fetchAll(PDO::FETCH_ASSOC) as $participant) { if($participant['invited_user_id']!==null) { $pdo->prepare("UPDATE user_group_gift_participants SET status='invited',invited_at=NOW(),updated_at=NOW() WHERE id=?")->execute([(int)$participant['id']]); mg_personal_workflows_notify($pdo,(int)$participant['invited_user_id'],'group_gift_invitation','Group gift invitation',(string)$group['title'],'/agent.php?view=group&group='.rawurlencode($publicId)); $notifications++; } } } $pdo->commit(); mg_audit('user_group_gift.status_updated','user_group_gift',['group_gift_id'=>$publicId,'from'=>$current,'to'=>$next,'notifications'=>$notifications,'money_collected'=>false],$userId); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } foreach(mg_personal_workflows_group_gifts($pdo,$userId)['owned'] as $row) if($row['id']===$publicId) return $row; throw new RuntimeException('Group gift not found.'); } function mg_personal_workflows_respond_group_invite(PDO $pdo, int $userId, string $participantPublicId, string $response, mixed $pledgeValue, bool $anonymous): array { if(!in_array($response,['join','decline'],true)) throw new InvalidArgumentException('Choose join or decline.'); $stmt=$pdo->prepare("SELECT gp.id,gp.group_gift_id,gp.status,g.min_contribution_cents,g.max_contribution_cents,g.goal_cents,g.status group_status,g.currency,g.public_id group_public_id
        FROM user_group_gift_participants gp INNER JOIN user_group_gifts g ON g.id=gp.group_gift_id
        WHERE gp.invited_user_id=? AND gp.public_id=? LIMIT 1"); $stmt->execute([$userId,$participantPublicId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if(!$row) throw new RuntimeException('Group gift invitation not found.'); if((string)$row['group_status']!=='open') throw new RuntimeException('This group gift is not open for pledges.'); if(!in_array((string)$row['status'],['invited','joined','declined'],true)) throw new RuntimeException('This invitation cannot be updated.'); $pledge=null; if($response==='join') { $pledge=mg_personal_workflows_cents($pledgeValue,false) ?? 0; if($pledge<1) throw new InvalidArgumentException('Enter a pledge amount.'); if($row['min_contribution_cents']!==null && $pledge<(int)$row['min_contribution_cents']) throw new InvalidArgumentException('Pledge is below the minimum contribution.'); if($row['max_contribution_cents']!==null && $pledge>(int)$row['max_contribution_cents']) throw new InvalidArgumentException('Pledge is above the maximum contribution.'); } $status=$response==='join'?'joined':'declined'; $pdo->beginTransaction(); try { $pdo->prepare('UPDATE user_group_gift_participants SET status=?,pledge_cents=?,is_anonymous=?,responded_at=NOW(),updated_at=NOW() WHERE id=?') ->execute([$status,$pledge,$anonymous?1:0,(int)$row['id']]); $pdo->prepare("UPDATE user_group_gifts g SET pledged_cents=(SELECT COALESCE(SUM(pledge_cents),0) FROM user_group_gift_participants WHERE group_gift_id=g.id AND status='joined'),updated_at=NOW() WHERE g.id=?") ->execute([(int)$row['group_gift_id']]); $pdo->commit(); mg_audit('user_group_gift.invite_responded','user_group_gift_participant',['group_gift_id'=>$row['group_public_id'],'participant_id'=>$participantPublicId,'response'=>$response,'pledge_cents'=>$pledge,'payment_collected'=>false],$userId); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } return ['participant_id'=>$participantPublicId,'status'=>$status,'pledge'=>mg_personal_workflows_money($pledge),'currency'=>(string)$row['currency'],'payment_collected'=>false]; } function mg_personal_workflows_record_external_pledge(PDO $pdo, int $userId, string $participantPublicId, mixed $pledgeValue): array { $stmt=$pdo->prepare("SELECT gp.id,gp.group_gift_id,g.min_contribution_cents,g.max_contribution_cents,g.currency,g.public_id group_public_id
        FROM user_group_gift_participants gp INNER JOIN user_group_gifts g ON g.id=gp.group_gift_id
        WHERE gp.organizer_user_id=? AND gp.private_contact_id IS NOT NULL AND gp.public_id=? AND g.status='open' LIMIT 1"); $stmt->execute([$userId,$participantPublicId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if(!$row) throw new RuntimeException('External group participant not found.'); $pledge=mg_personal_workflows_cents($pledgeValue,false) ?? 0; if($pledge<1) throw new InvalidArgumentException('Enter a pledge amount.'); if($row['min_contribution_cents']!==null && $pledge<(int)$row['min_contribution_cents']) throw new InvalidArgumentException('Pledge is below the minimum contribution.'); if($row['max_contribution_cents']!==null && $pledge>(int)$row['max_contribution_cents']) throw new InvalidArgumentException('Pledge is above the maximum contribution.'); $pdo->beginTransaction(); try { $pdo->prepare("UPDATE user_group_gift_participants SET status='joined',pledge_cents=?,responded_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$pledge,(int)$row['id']]); $pdo->prepare("UPDATE user_group_gifts g SET pledged_cents=(SELECT COALESCE(SUM(pledge_cents),0) FROM user_group_gift_participants WHERE group_gift_id=g.id AND status='joined'),updated_at=NOW() WHERE g.id=?")->execute([(int)$row['group_gift_id']]); $pdo->commit(); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; } mg_audit('user_group_gift.external_pledge_recorded','user_group_gift_participant',['group_gift_id'=>$row['group_public_id'],'participant_id'=>$participantPublicId,'pledge_cents'=>$pledge,'payment_collected'=>false],$userId); return ['participant_id'=>$participantPublicId,'status'=>'joined','pledge'=>mg_personal_workflows_money($pledge),'currency'=>(string)$row['currency'],'payment_collected'=>false]; } 